namespace cb {
std::vector<Hypothesis> decode_ctc(const StreamState& s,bool finalized){ auto lp = log_softmax_all(s.logits,s.frames,s.vocab); std::map<Prefix,PrefixMass> beam; beam[Prefix{}].pb=0.0; for(uint32_t t=0;t<s.frames;t++){ std::map<Prefix,PrefixMass> next; for(auto& [p,m]:beam){ add_blank(next,p,m,lp[t][s.blank]); for(uint32_t v=0;v<s.vocab;v++) if(v!=s.blank) add_label(next,p,m,int(v),lp[t][v]); } beam = prune_beam(next,s.beam,s.prune); } std::vector<Hypothesis> hyps; for(auto& [p,m]:beam){ Hypothesis h; h.ids=p; h.text=text_for_ids(p,s.tokens); h.acoustic=prefix_acoustic(m); h.bias=completion_bias(h.text,s.biases,finalized); h.total=h.acoustic+h.bias; h.spans=align_tokens(p,s.logits,s.frames,s.vocab,s.blank); hyps.push_back(h); } std::sort(hyps.begin(),hyps.end(),hyp_less); if(hyps.size()>s.topn) hyps.resize(s.topn); assign_confidence(hyps); return hyps; }
}
